#!/usr/bin/env node
/* Regenerate the shields.io endpoint badge JSONs from sources.json and
 * sources-ci.json. ES5 only (the repo's declared runtime is Node >=0.10).
 *
 * Usage (repo root):
 *   node scripts/update-benchmark-badges.js
 *
 * sources.json  — hand-recorded reference-host (Zen4) numbers; endpoint
 *                   JSONs served from the feat/ci-benchmark-badge branch.
 * sources-ci.json — CI-runner numbers, generated by the ci-benchmark-badge
 *                   workflow monthly (30th 20:00 UTC); endpoint JSONs
 *                   served from a public gist (fork workflow tokens are
 *                   read-only, so the gist keeps repo-write credentials
 *                   out of CI). The gist id lives in sources-ci.json.
 * The endpoint JSONs (benchmarks/badges/*.json) are regenerated here.
 */
'use strict';
var fs = require('fs');
var path = require('path');

var BADGES_DIR = path.join(__dirname, '..', 'benchmarks', 'badges');

function loadSources(file) {
  var p = path.join(BADGES_DIR, file);
  if (!fs.existsSync(p)) {
    console.error('missing ' + p);
    process.exit(1);
  }
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

var src = loadSources('sources.json');
var srcCi = loadSources('sources-ci.json');
if (!Array.isArray(src.badges) || src.badges.length === 0) {
  console.error('sources.json: no badges array');
  process.exit(1);
}
/* The CI source is generated by the workflow; a missing/empty badges
 * array means the measurements never landed — fail rather than
 * republish stale endpoint values. */
if (!Array.isArray(srcCi.badges) || srcCi.badges.length === 0) {
  console.error('sources-ci.json: no badges array (workflow measurement step failed?)');
  process.exit(1);
}

var md = '';
function emit(repo, base, b) {
  if (!b.id || !b.message) {
    console.error('badge missing id/message: ' + JSON.stringify(b));
    process.exit(1);
  }
  // label is optional — empty label renders as "message only" in shields.io
  if (typeof b.label !== 'string') b.label = '';
  var ep = {
    schemaVersion: 1,
    label: b.label,
    message: b.message,
    color: b.color || 'brightgreen'
  };
  if (b.detail) ep.labelColor = '555';
  var file = path.join(BADGES_DIR, b.id + '.json');
  fs.writeFileSync(file, JSON.stringify(ep, null, 2) + '\n');
  var url = base + b.id + '.json';
  var shields = 'https://img.shields.io/endpoint?url=' + encodeURIComponent(url) +
                '&style=flat-square';
  md += '[![' + b.label + '](' + shields + ')](https://github.com/' +
        repo + '#throughput)\n';
  console.log('wrote ' + file);
}

/* Branch-served (Zen4) and gist-served (CI) endpoint bases. */
var zen4Base = 'https://raw.githubusercontent.com/' + src.repo + '/' +
               src.branch + '/benchmarks/badges/';
var ciBase = 'https://gist.githubusercontent.com/' + srcCi.gistUser + '/' +
             srcCi.gistId + '/raw/';

src.badges.forEach(function (b) { emit(src.repo, zen4Base, b); });
srcCi.badges.forEach(function (b) { emit(srcCi.repo, ciBase, b); });

console.log('\nREADME snippet:\n' + md);
